return {
    highlightMatching = function(p1, p2, p3) -- highlightMatching | line: 2
        if p2 == nil then
            return ""
        end

        if p3 == nil then
            return p2
        end

        local v2 = string.sub(p2, 0, #p3)

        if string.lower(p3) ~= string.lower(v2) then
            return p2
        end

        local v4 = string.sub(p2, #p3 + 1)

        return (("<font color=\"#%*\">%*</font>%*"):format(p1:ToHex(), v2, v4))
    end
}
